server.registerTool(
  "push_flow",
  {
    title: "Push the linked file into the project",
    description: "Send the linked .flow file to Prompt Studio. Snapshots first, and refuses if the project moved on since the file was pulled.",
    inputSchema: {
      project_id: external_exports.string().default("").describe("Omit when the repository links one project"),
      // `merge` for the same reason `write_flow` uses it: `replace` rebuilds the
      // document from the file, which mints new ids for every screen, module
      // and edge. Comments are anchored to those ids, so one push that changed
      // nothing orphaned every pinned comment on the project.
      mode: external_exports.enum(["merge", "replace"]).default("merge"),
      label: external_exports.string().default("")
    }
  },
  async ({ project_id, mode, label }) => guard(async () => {
    const link = resolveLink(project_id || void 0);
    if (!link) return NO_LINK;
    const found = readLinks();
    const root = found?.root ?? process.cwd();
    const path = flowPathOf(link, root);
    const source = readFileSync3(path, "utf8");
    const project = await api.getProject(link.projectId);
    if (project.doc_version !== link.lastSyncedVersion) {
      return [
        `Refused. ${relative(root, path)} was pulled at version ${link.lastSyncedVersion}, and the project is now at version ${project.doc_version}.`,
        "",
        "Somebody changed it in the studio since. Run pull_flow to bring the file up to date \u2014 commit or stash your edits first \u2014 then reapply and push."
      ].join("\n");
    }
    const applied = applyFlow(readDoc(project.doc), source, mode);
    if (!applied.ok) {
      return `Refused \u2014 ${relative(root, path)} does not parse:

${applied.issues.map((i) => `  ${i}`).join("\n")}`;
    }
    let snapshot = "";
    try {
      const version2 = await api.saveVersion(
        link.projectId,
        label.trim() || `Before pushing ${relative(root, path)}`
      );
      snapshot = `Snapshot saved as "${version2.label}".`;
    } catch (error2) {
      snapshot = `Could not snapshot first (${failure(error2)}). Pushing anyway.`;
    }
    const saved = await api.saveDocument(link.projectId, {
      doc: applied.doc,
      base_version: project.doc_version,
      schema_version: SCHEMA_VERSION
    });
    upsertLink(root, {
      ...link,
      lastSyncedVersion: saved.doc_version,
      lastSyncedAt: (/* @__PURE__ */ new Date()).toISOString()
    });
    return [snapshot, applied.summary, `Pushed. Project is now at version ${saved.doc_version}.`].join("\n");
  })
);
server.registerTool(
  "sync_status",
  {
    title: "Sync status",
    description: "Whether the linked .flow file matches the project, and which way it has drifted.",
    inputSchema: {
      project_id: external_exports.string().default("")
    }
  },
  async ({ project_id }) => guard(async () => {
    const found = readLinks();
    if (!found || !Object.keys(found.links.projects).length) return NO_LINK;
    const links = project_id ? [found.links.projects[project_id]].filter(Boolean) : Object.values(found.links.projects);
    const lines = [];
    for (const link of links) {
      const project = await api.getProject(link.projectId);
      const path = flowPathOf(link, found.root);
      let fileMatches = false;
      try {
        fileMatches = readFileSync3(path, "utf8").trim() === toFlow(project.doc).trim();
      } catch {
        lines.push(`${link.projectName}: ${relative(found.root, path)} is missing. Run pull_flow.`);
        continue;
      }
      const behind = project.doc_version !== link.lastSyncedVersion;
      lines.push(
        fileMatches && !behind ? `${link.projectName}: in sync at version ${project.doc_version}.` : behind ? `${link.projectName}: the studio moved on (file pulled at v${link.lastSyncedVersion}, project at v${project.doc_version}). Run pull_flow.` : `${link.projectName}: the file has local edits not yet pushed. Run push_flow.`
      );
    }
    return lines.join("\n");
  })
);
